out={}
for trans in ('zl','it','rf'):
 pages,_=corpus.split_pages('practice',trans); toks=dsl.select(dsl.tokens(pages),{'unit':['P'],'certain':True}); by=defaultdict(lambda:Counter())
 for t in toks:
  if t['language'] not in ('A','B'):continue
