 def summarize(section, hand=None):
  groups={lang:[v for (p,l,s,h),v in by.items() if l==lang and (section is None or s==section) and (hand is None or h==hand)] for lang in ('A','B')}; res={}
  for lang,vs in groups.items():
   tot=sum(v['n'] for v in vs);res[lang]={'pages':len(vs),'tokens':tot,'ed':sum(v['ed'] for v in vs),'od':sum(v['od'] for v in vs),'mean_page_ed_share':sum(v['ed']/v['n'] for v in vs)/len(vs) if vs else None,'mean_page_od_share':sum(v['od']/v['n'] for v in vs)/len(vs) if vs else None}
  if all(groups.values()):
   rng=random.Random(503); ds=[]
   for i in range(2000):
    vals={}
    for lang,vs in groups.items():
     sample=[rng.choice(vs) for _ in vs]; vals[lang]=sum(v['ed'] for v in sample)/sum(v['n'] for v in sample)
    ds.append(vals['B']-vals['A'])
   ds.sort();res['ed_rate_difference_B_minus_A']=(res['B']['ed']/res['B']['tokens'])-(res['A']['ed']/res['A']['tokens']);res['page_bootstrap_95']=[ds[49],ds[1949]]
  return res
 out[trans]={'all':summarize(None),'herbal_H':summarize('H'),'hand3_stars_S':summarize('S','3'),'page_groups':dict(Counter(str((l,s,h)) for (p,l,s,h) in by))}
